import{_ as t,o as i,c as n,a3 as s}from"./chunks/framework.BNNhFWPR.js";const g=JSON.parse('{"title":"Writing documentation","description":"Page ids, references to pages and C++ symbols, and how to preview your changes.","frontmatter":{"id":"writing-documentation","title":"Writing documentation","order":1,"description":"Page ids, references to pages and C++ symbols, and how to preview your changes.","editUrl":"https://github.com/ATMO-Engine/docs/edit/main/content/en/contributing/writing-documentation.md"},"headers":[],"relativePath":"contributing/writing-documentation.md","filePath":"en/contributing/writing-documentation.md"}'),a={name:"contributing/writing-documentation.md"};function o(r,e,d,h,c,l){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="writing-documentation" tabindex="-1">Writing documentation <a class="header-anchor" href="#writing-documentation" aria-label="Permalink to &quot;Writing documentation&quot;">​</a></h1><p>The site has three sources:</p><ul><li><strong>Guides and manual</strong> — Markdown files in the engine repository, under <code>docs/en/</code>. Update them in the pull request that changes the behavior they describe.</li><li><strong>API reference</strong> — generated from the engine&#39;s source comments by Doxygen. To change it, edit the comments in the engine repository.</li><li><strong>Site pages</strong> — the home page and these contributing pages, in this repository under <code>content/en/</code>.</li></ul><p>When the site is built, the engine&#39;s <code>docs/en/</code> pages are copied into <code>content/en/</code>, so both sets of pages form one tree and can reference each other. A page can&#39;t exist in both repositories.</p><h2 id="local" tabindex="-1">Running the site locally <a class="header-anchor" href="#local" aria-label="Permalink to &quot;Running the site locally {#local}&quot;">​</a></h2><p>You need Node.js 22 or newer, <a href="https://pnpm.io" target="_blank" rel="noreferrer">pnpm</a> and <a href="https://www.doxygen.nl" target="_blank" rel="noreferrer">Doxygen</a>, with this repository cloned next to the engine (<code>../atmo</code>).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # run Doxygen on ../atmo and build the API model</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # http://localhost:5173/latest/</span></span></code></pre></div><p>Set <code>ATMO_ENGINE_DIR</code> if the engine lives somewhere else. Edits to the engine&#39;s <code>docs/</code> pages show up in the dev server right away; run <code>pnpm api</code> again after changing engine comments.</p><p>The copied engine pages are ignored by git in this repository. A new page owned by this repository must be added to the exceptions at the end of its <code>.gitignore</code>.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages {#pages}&quot;">​</a></h2><p>Every Markdown file under the engine&#39;s <code>docs/en/</code> and this repository&#39;s <code>content/en/</code> is a page. Its frontmatter controls how it is referenced and listed:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">id: building-from-source # stable id used by references, required to be referenced</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">title: Building from source # sidebar and link text (defaults to the first heading)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">order: 1 # position in its sidebar section (lower first, then alphabetical)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Install the toolchain and build the engine. # used in link previews and search results</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span></code></pre></div><p>Folders become sidebar sections; a folder&#39;s <code>index.md</code> gives the section its title, link and <code>order</code>. Add <code>sidebar: false</code> to keep a page or folder out of the sidebar.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References {#references}&quot;">​</a></h2><p>Link to other pages and to C++ symbols with double brackets. References are resolved when the site is built, so links survive files being moved or renamed, and <strong>a broken reference fails the build</strong>.</p><table tabindex="0"><thead><tr><th>You write</th><th>Links to</th></tr></thead><tbody><tr><td><code>[[building-from-source]]</code></td><td>The page with that <code>id</code>, using its title as link text</td></tr><tr><td><code>[[building-from-source#build]]</code></td><td>A heading on that page, using the heading as link text</td></tr><tr><td><code>[[building-from-source|this guide]]</code></td><td>The same page, with custom link text</td></tr><tr><td><code>[[atmo::core::Engine]]</code></td><td>The API page of a C++ symbol, shown as code</td></tr><tr><td><code>[[EntityRegistry]]</code></td><td>The same, matched on the end of the qualified name</td></tr><tr><td><code>[[Engine::run()]]</code></td><td>A member function (trailing <code>()</code> is optional)</td></tr><tr><td><code>[[page:...]]</code> / <code>[[cpp:...]]</code></td><td>Forces a page id or a C++ symbol when a name could be both</td></tr></tbody></table><p>Hovering a reference shows the target&#39;s description (the page&#39;s <code>description</code>, or the symbol&#39;s brief comment).</p><h3 id="symbol-names" tabindex="-1">Symbol names <a class="header-anchor" href="#symbol-names" aria-label="Permalink to &quot;Symbol names {#symbol-names}&quot;">​</a></h3><p>A C++ reference can use any trailing part of the qualified name, as long as it matches exactly one symbol. When a type and its constructor both match (<code>ResourceManager</code>), the type wins. If a name is ambiguous, the build lists the candidates; write more of the name, e.g. <code>[[core::Engine]]</code> instead of <code>[[Engine]]</code>.</p><h3 id="anchors" tabindex="-1">Heading anchors <a class="header-anchor" href="#anchors" aria-label="Permalink to &quot;Heading anchors {#anchors}&quot;">​</a></h3><p>Anchors are generated from heading text. To keep a link stable when a heading is reworded, give the heading an explicit id:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Clone and build {#build}</span></span></code></pre></div><p>Anchors on the current page don&#39;t need a reference: use a regular link, <code>[text](#anchor)</code>.</p><h2 id="style" tabindex="-1">Style <a class="header-anchor" href="#style" aria-label="Permalink to &quot;Style {#style}&quot;">​</a></h2><p>Formatting is enforced by Prettier (4 spaces, double quotes). In this repository, run <code>pnpm format</code> before committing; the <code>pnpm format:check</code> script fails on unformatted files. For engine pages, run <code>pnpm exec prettier --write ../atmo/docs</code> from this repository.</p><h2 id="engine-checks" tabindex="-1">Checks on engine pull requests <a class="header-anchor" href="#engine-checks" aria-label="Permalink to &quot;Checks on engine pull requests {#engine-checks}&quot;">​</a></h2><p>The engine&#39;s <code>docs</code> workflow runs on every pull request and push. It builds the site from the pull request&#39;s checkout with the tooling of this repository&#39;s <code>main</code> branch, so it fails when a page is not formatted, or when a reference is broken: a renamed class, a removed page or heading. Fix the reference in the same pull request.</p>`,27)])])}const u=t(a,[["render",o]]);export{g as __pageData,u as default};
